// Lo que devolvió Natural Language, pasado a palabras simples.
const r = $json;
const s = r.documentSentiment ?? { score: 0, magnitude: 0 };

// score va de -1 (muy negativo) a 1 (muy positivo).
// magnitude mide cuánta emoción hay en todo el texto, sin importar el signo.
let tono;
if (s.score >= 0.25) tono = 'positivo';
else if (s.score <= -0.25) tono = 'negativo';
else if (s.magnitude >= 1) tono = 'mixto: hay cosas buenas y cosas malas';
else tono = 'neutral';

const TIPOS = {
  PERSON: 'persona',
  LOCATION: 'lugar',
  ORGANIZATION: 'organización',
  EVENT: 'evento',
  WORK_OF_ART: 'obra',
  CONSUMER_GOOD: 'producto',
  OTHER: 'otro',
  UNKNOWN: 'otro',
};
// Teléfonos, direcciones, números, precios y fechas quedan afuera del resumen: así no se muestran datos personales.
const entidades = (r.entities ?? [])
  .filter((e) => TIPOS[e.type])
  .sort((a, b) => (b.mentions?.length ?? 0) - (a.mentions?.length ?? 0))
  .slice(0, 5)
  .map((e) => `${e.name} (${TIPOS[e.type]})`);

// La frase más positiva y la más negativa, para ver de dónde sale el tono.
const frases = (r.sentences ?? []).map((f) => ({ texto: f.text?.content ?? '', score: f.sentiment?.score ?? 0 }));
const ordenadas = [...frases].sort((a, b) => b.score - a.score);
const mejor = ordenadas[0];
const peor = ordenadas[ordenadas.length - 1];

const form = $('Formulario de opiniones').item.json;
return {
  json: {
    tema: form.tema,
    opinion: form.opinion,
    tono,
    puntaje: s.score,
    intensidad: s.magnitude,
    entidades,
    entidades_texto: entidades.length ? entidades.join(', ') : 'nada en particular',
    frase_mas_positiva: mejor && mejor.score > 0 ? mejor.texto : '',
    frase_mas_negativa: peor && peor.score < 0 ? peor.texto : '',
    idioma: r.languageCode ?? '',
  },
};

